use telperion_core::{branching,presets::Preset,surface}; fn main(){for name in ["oregon-white-oak","norway-spruce"]{for seed in [1,7]{let mut p=Preset::from_id(name).unwrap().parameters();p.skeleton.seed=seed;let t=branching::generate(&p.skeleton,p.radii).unwrap();eprintln!("CASE {name} {seed}");let m=surface::build(&t.tree,p.skeleton.envelope.height,&p.surface).unwrap();eprintln!("RESULT vertices={} dropped={}",m.positions.len()/3,m.dropped);}}}